package com.bank.matrix.service;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the Kth smallest value in a row-sorted matrix via early-stopped K-way merge.
public class FeeMatrixService {
    private static final Logger log = Logger.getLogger(FeeMatrixService.class.getName());

    public int kthSmallest(int[][] matrix, int k) {
        int n = matrix.length;
        // Heap entry: {value, row, col}; ordered by value.
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int r = 0; r < Math.min(n, k); r++) {
            pq.add(new int[]{matrix[r][0], r, 0});     // first column of each row
        }
        int result = -1;
        for (int count = 0; count < k && !pq.isEmpty(); count++) {
            int[] top = pq.poll();                     // current global minimum
            result = top[0];
            int row = top[1], col = top[2];
            if (col + 1 < n) {
                pq.add(new int[]{matrix[row][col + 1], row, col + 1});   // next in row
            }
        }
        final int ans = result;
        log.info(() -> "Kth smallest (k=" + k + ") = " + ans);
        return result;
    }
}
