package com.bank.matrix;

import com.bank.matrix.service.FeeMatrixService;
import java.util.logging.Logger;

public class FeeMatrixApplication {
    private static final Logger log = Logger.getLogger(FeeMatrixApplication.class.getName());

    public static void main(String[] args) {
        FeeMatrixService service = new FeeMatrixService();
        int[][] matrix = {
            {2, 6, 8},      // fees rise left to right and top to bottom
            {3, 7, 10},
            {5, 8, 11}
        };
        int k = 5;
        int kth = service.kthSmallest(matrix, k);
        log.info("The " + k + "th smallest fee is Rs." + kth);
    }
}
